-- pgTAP: the Analytics checker rows (`20271122090000_analytics_checker_rows.sql`,
-- docs/ANALYTICS.md Step 2).
--
-- What has to hold:
--
--   * security: the writer is a definer, the page and the readers invoker;
--     every one has an empty search_path, carries the R6.2 gate and is listed
--     in entitlement_gates; authenticated only; the two tables have no client
--     write grant and RLS on; both are in account_data_inventory;
--   * the fixture (`core/rail-stats/tests/data/analytics/rows/`, embedded
--     below and held equal to the files by `tests/test/analyticsRows.test.ts`):
--     its hands saved through save_hand_analysis, every one is pending; its
--     rows (what analyticsRows derives) saved through analytics_rows_save sum
--     to exactly `sums.json` - the sums the desktop store's reader returns
--     over the same decisions (`core/rail-store/tests/checker.rs`);
--   * idempotence: saving again changes nothing; a row whose decision does not
--     exist is dropped; a hand saved at another membership version leaves the
--     sums and is pending again until saved back;
--   * the filters (dates, seat, pot kind, membershipVersion) narrow the rows
--     and the hand count; the examples come costliest first with the cards;
--   * a prune of the analysis takes the rows and markers with it;
--   * one account never reads or writes another's; bad input and anon are
--     refused.

begin;

create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;

select plan(33);

insert into auth.users (id, email, email_confirmed_at, created_at) values
  ('00000000-0000-0000-0000-0000000ac0a1', 'checker.a@example.com', now(), now()),
  ('00000000-0000-0000-0000-0000000ac0b1', 'checker.b@example.com', now(), now());

create function pg_temp.act_as(p_uid uuid) returns void language plpgsql as $$
begin
  execute 'reset role';
  perform set_config('request.jwt.claims', json_build_object('sub', p_uid, 'role', 'authenticated')::text, true);
  execute 'set local role authenticated';
end;
$$;
grant execute on function pg_temp.act_as(uuid) to anon, authenticated;

