-- Case n (1-based) is hand ...ac0NNN of A, played on 2026-11-(n) at noon.
create function pg_temp.hid(p_n bigint) returns uuid language sql immutable as $$
  select ('00000000-0000-0000-0000-0000000ac' || lpad(p_n::text, 3, '0'))::uuid;
$$;
grant execute on function pg_temp.hid(bigint) to authenticated;

-- ----------------------------------------------------------- security --

select ok(
  (select p.prosecdef from pg_proc p where p.oid = 'public.analytics_rows_save(jsonb)'::regprocedure)
  and (select bool_and(not p.prosecdef) from pg_proc p
       where p.oid in ('public.analytics_rows_pending(text, text, uuid, integer)'::regprocedure,
                       'public.analytics_checker(jsonb)'::regprocedure,
                       'public.analytics_checker_examples(jsonb, text, text, text, text, text, integer)'::regprocedure)),
  'the writer is a definer; the page and the two readers are invoker');
select ok(
  (select bool_and(coalesce(array_to_string(p.proconfig, ','), '') like '%search_path=""%')
          and bool_and(position('public.require_entitlement(''analysis'')' in pg_get_functiondef(p.oid)) > 0)
          and count(*) = 4
   from pg_proc p
   where p.oid in ('public.analytics_rows_save(jsonb)'::regprocedure,
                   'public.analytics_rows_pending(text, text, uuid, integer)'::regprocedure,
                   'public.analytics_checker(jsonb)'::regprocedure,
                   'public.analytics_checker_examples(jsonb, text, text, text, text, text, integer)'::regprocedure)),
  '... every one has an empty search_path and the R6.2 gate');
select is(
  (select count(*)::int from public.entitlement_gates
   where feature = 'analysis'
     and function_sig in ('public.analytics_rows_save(jsonb)', 'public.analytics_rows_pending(text,text,uuid,integer)',
                          'public.analytics_checker(jsonb)',
                          'public.analytics_checker_examples(jsonb,text,text,text,text,text,integer)')),
  4, '... and is listed in entitlement_gates (analysis)');
select ok(
  has_function_privilege('authenticated', 'public.analytics_rows_save(jsonb)', 'execute')
  and has_function_privilege('authenticated', 'public.analytics_checker(jsonb)', 'execute')
  and not has_function_privilege('anon', 'public.analytics_rows_save(jsonb)', 'execute')
  and not has_function_privilege('anon', 'public.analytics_rows_pending(text, text, uuid, integer)', 'execute')
  and not has_function_privilege('anon', 'public.analytics_checker(jsonb)', 'execute')
  and not has_function_privilege('anon', 'public.analytics_checker_examples(jsonb, text, text, text, text, text, integer)', 'execute'),
  '... executable by authenticated, not by anon');
select ok(
  (select count(*) = 0 from information_schema.role_table_grants
   where table_schema = 'public' and table_name in ('analysis_checker_rows', 'analysis_checker_hands')
     and grantee in ('anon', 'authenticated') and privilege_type <> 'SELECT')
  and (select bool_and(c.relrowsecurity) from pg_class c
       where c.oid in ('public.analysis_checker_rows'::regclass, 'public.analysis_checker_hands'::regclass))
  and (select count(*) = 2 from public.account_data_inventory
       where name in ('public.analysis_checker_rows', 'public.analysis_checker_hands') and export = 'derived'),
  'the tables: no client write grant, RLS on, both in the account inventory');

-- ------------------------------------------------------------ the data --

insert into public.hands (id, owner_id, hand_key, phf, standard_text, site, hero_seat, hero_position,
                          game_format, currency, currency_minor_units, small_blind, big_blind, hero_profit,
                          hero_cards, played_at)
select pg_temp.hid(n), '00000000-0000-0000-0000-0000000ac0a1', 'weplay:chk' || n,
       jsonb_build_object('schema', 'phf/1',
                          'game', jsonb_build_object('variant', 'holdem', 'limit', 'nl', 'format', 'cash',
                                                     'bigBlind', 100, 'smallBlind', 50),
                          'players', '[]'::jsonb, 'actions', '[]'::jsonb),
       'std', 'weplay', 1, case when n % 2 = 0 then 'CO' else 'BTN' end, 'cash', 'USD', 100, 50, 100, 0,
       array['As', 'Kd'], ('2026-11-01T12:00:00Z'::timestamptz + (n - 1) * interval '1 day')
from jsonb_array_elements(pg_temp.cases() -> 'cases') with ordinality t(c, n);

-- The fixture's decisions, in save_hand_analysis' shape.
create function pg_temp.analysis_payload() returns jsonb language sql as $$
  select jsonb_agg(jsonb_build_object(
           'hand_id', pg_temp.hid(n), 'analysis_version', 'analysis/50', 'hero_seat', 1,
           'status', (select case when bool_and(d ->> 'status' = 'analysed') then 'full'
                                  when bool_or(d ->> 'status' = 'analysed') then 'partial' else 'not-analysed' end
                      from jsonb_array_elements(c -> 'decisions') d),
           'reason', (select case when bool_or(d ->> 'status' = 'analysed') then null else 'no-reference' end
                      from jsonb_array_elements(c -> 'decisions') d),
           'pot_type', 'single-raised', 'grade', null, 'score', null, 'ev_loss_bb', 0, 'ev_loss_pot', 0,
           'approximations', '[]'::jsonb,
           'decisions', (
             select jsonb_agg(d || jsonb_build_object(
                      'node', 'n', 'scenario', coalesce(d -> 'facts' ->> 'scenario', 'x'), 'source', 'solver',
                      'grade', case when d ->> 'status' = 'analysed' then 'good' end, 'score', null,
                      'reason', case when d ->> 'status' = 'analysed' then null else 'no-reference' end,
                      'ev_loss_pot', null, 'freq_diff', null, 'flags', '[]'::jsonb, 'approximations', '[]'::jsonb,
                      'facing_bet', false, 'pot_bb', 5, 'pot_odds', null, 'mdf', null))
             from jsonb_array_elements(c -> 'decisions') d)) order by n)
  from jsonb_array_elements(pg_temp.cases() -> 'cases') with ordinality t(c, n);
$$;
-- The fixture's rows, in analytics_rows_save's shape, at a membership version.
create function pg_temp.rows_payload(p_mv text) returns jsonb language sql as $$
  select jsonb_agg(jsonb_build_object(
           'hand_id', pg_temp.hid(n), 'analysis_version', 'analysis/50', 'membership_version', p_mv,
           'rows', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'ord', r -> 'ord', 'stat', r -> 'stat', 'taken', r -> 'taken', 'ref_share', r -> 'refShare',
                      'best_in', r -> 'bestIn', 'size', r -> 'size', 'hand_class', r -> 'handClass',
                      'spot', r -> 'spot', 'multiway', r -> 'multiway'))
             from jsonb_array_elements(h -> 'rows') r), '[]'::jsonb)) order by n)
  from jsonb_array_elements(pg_temp.rows()) with ordinality t(h, n);
$$;
grant execute on function pg_temp.analysis_payload(), pg_temp.rows_payload(text) to authenticated;

select pg_temp.act_as('00000000-0000-0000-0000-0000000ac0a1');
select is((public.save_hand_analysis(pg_temp.analysis_payload()) ->> 'inserted')::int,
          jsonb_array_length(pg_temp.cases() -> 'cases'), 'A''s fixture hands are analysed (save_hand_analysis)');
select is((select count(*)::int from public.analytics_rows_pending('analysis/50', 'analytics/1', null, 200)),
          jsonb_array_length(pg_temp.cases() -> 'cases'), 'every one is pending');
select is((select d from public.analytics_rows_pending('analysis/50', 'analytics/1', null, 1) p(id, phf, st, k, s, pv, sf, ca, d)),
          (select jsonb_agg(jsonb_build_object('ord', d -> 'ord', 'action_index', d -> 'action_index', 'status', d -> 'status',
                                               'options', d -> 'options', 'ev_loss_bb', d -> 'ev_loss_bb', 'facts', d -> 'facts')
                            order by (d ->> 'ord')::int)
           from jsonb_array_elements(pg_temp.cases() -> 'cases' -> 0 -> 'decisions') d),
          '... with its stored decisions, what analyticsRows reads');
select is((select count(*)::int from public.analytics_rows_pending('analysis/50', 'analytics/1', pg_temp.hid(20), 200)),
          jsonb_array_length(pg_temp.cases() -> 'cases') - 20, '... a page at a time (after a hand id)');

select is(public.analytics_rows_save(pg_temp.rows_payload('analytics/1')) - 'received',
          jsonb_build_object('saved', jsonb_array_length(pg_temp.cases() -> 'cases'), 'missing', 0,
                             'rows', (select sum(jsonb_array_length(h -> 'rows'))::int from jsonb_array_elements(pg_temp.rows()) h)),
          'the rows are saved: every hand, every row');
select is(public.analytics_checker('{"analysisVersion":"analysis/50"}') -> 'groups', pg_temp.sums() -> 'groups',
          'analytics_checker sums to the fixture''s sums.json (the desktop store''s answer)');
select is((public.analytics_checker('{"analysisVersion":"analysis/50"}') -> 'hands')::int, (pg_temp.sums() ->> 'hands')::int,
          '... over every hand');
select is((public.analytics_checker('{"analysisVersion":"analysis/50"}') ->> 'pending')::int, 0, '... none pending');
select is((select count(*)::int from public.analytics_rows_pending('analysis/50', 'analytics/1', null, 200)), 0,
          'the backfill''s work list is empty');

-- Idempotence.
select is(public.analytics_rows_save(pg_temp.rows_payload('analytics/1')) ->> 'rows',
          (select sum(jsonb_array_length(h -> 'rows'))::text from jsonb_array_elements(pg_temp.rows()) h),
          'saving again writes the same rows');
select is(public.analytics_checker('{"analysisVersion":"analysis/50"}') -> 'groups', pg_temp.sums() -> 'groups',
          '... and the sums do not move');
select is(public.analytics_rows_save(jsonb_build_array(jsonb_build_object(
            'hand_id', pg_temp.hid(1), 'analysis_version', 'analysis/50', 'membership_version', 'analytics/1',
            'rows', (pg_temp.rows_payload('analytics/1') -> 0 -> 'rows') || jsonb_build_array(jsonb_build_object(
              'ord', 99, 'stat', 'vpip', 'taken', true, 'ref_share', 0.5, 'best_in', true, 'size', '',
              'hand_class', '', 'spot', '|unopened|BTN|', 'multiway', false))))) ->> 'rows',
          jsonb_array_length(pg_temp.rows() -> 0 -> 'rows')::text,
          'a row whose decision does not exist is dropped');

-- Another membership version.
select is((public.analytics_rows_save(jsonb_build_array(pg_temp.rows_payload('analytics/2') -> 0)) ->> 'saved')::int, 1,
          'a hand saved at analytics/2 ...');
select is((public.analytics_checker('{"analysisVersion":"analysis/50"}') ->> 'hands')::int,
          (pg_temp.sums() ->> 'hands')::int - 1, '... leaves the analytics/1 sums');
select is((select array_agg(id) from public.analytics_rows_pending('analysis/50', 'analytics/1', null, 200)),
          array[pg_temp.hid(1)], '... and is pending again at analytics/1');
select is((public.analytics_checker('{"analysisVersion":"analysis/50","membershipVersion":"analytics/2"}') ->> 'hands')::int, 1,
          '... while analytics/2 reads it');
select is(public.analytics_rows_save(jsonb_build_array(pg_temp.rows_payload('analytics/1') -> 0)) ->> 'saved', '1',
          'saved back at analytics/1');
select is(public.analytics_checker('{"analysisVersion":"analysis/50"}') -> 'groups', pg_temp.sums() -> 'groups',
          '... the sums are the fixture''s again');

-- Filters.
select is(public.analytics_checker('{"analysisVersion":"analysis/50","to":"2026-10-01T00:00:00Z"}') - 'pending' - 'analysisVersion' - 'membershipVersion',
          '{"hands": 0, "groups": []}'::jsonb, 'a range before every hand: nothing');
select is((select array[(c ->> 'hands')::int, (select sum((g ->> 'opps')::int)::int from jsonb_array_elements(c -> 'groups') g)]
           from (select public.analytics_checker('{"analysisVersion":"analysis/50","position":"CO"}') c) x),
          array[(select count(*)::int from jsonb_array_elements(pg_temp.cases() -> 'cases') with ordinality t(c, n) where n % 2 = 0),
                (select coalesce(sum(jsonb_array_length(h -> 'rows')), 0)::int
                 from jsonb_array_elements(pg_temp.rows()) with ordinality t(h, n) where n % 2 = 0)],
          'the seat filter keeps the hands of that seat and their rows');
select is((select sum((g ->> 'opps')::int)::int
           from jsonb_array_elements(public.analytics_checker('{"analysisVersion":"analysis/50","potKind":"mw"}') -> 'groups') g),
          (select count(*)::int from jsonb_array_elements(pg_temp.rows()) h, jsonb_array_elements(h -> 'rows') r
           where (r ->> 'multiway')::boolean),
          'potKind mw keeps the multiway decisions');

-- Examples.
select is((select array_agg((r ->> 'evLossBb')::numeric order by n)
           from jsonb_array_elements(public.analytics_checker_examples('{"analysisVersion":"analysis/50"}', 'vpip', null, null, null, 'high', 3) -> 'rows')
                with ordinality t(r, n)),
          (select array_agg(e order by e desc) from (
             select (r ->> 'evLossBb')::numeric as e
             from jsonb_array_elements(pg_temp.rows()) h, jsonb_array_elements(h -> 'rows') r
             where r ->> 'stat' = 'vpip' and (r ->> 'taken')::boolean and r ->> 'refShare' is not null
             order by 1 desc limit 3) x),
          'the examples: the costliest decisions that took the class, first');
select is((public.analytics_checker_examples('{"analysisVersion":"analysis/50"}', 'vpip', null, null, null, 'high', 1) -> 'rows' -> 0)
            -> 'cards', '["As","Kd"]'::jsonb, '... with the hand''s cards');

-- Another account.
select pg_temp.act_as('00000000-0000-0000-0000-0000000ac0b1');
select is(public.analytics_checker('{"analysisVersion":"analysis/50"}') -> 'groups', '[]'::jsonb, 'B reads none of A''s rows');
select is(public.analytics_rows_save(pg_temp.rows_payload('analytics/1')) ->> 'saved', '0', '... and writes none');

-- Refusals.
select pg_temp.act_as('00000000-0000-0000-0000-0000000ac0a1');
select throws_ok($$ select public.analytics_rows_save('[{"hand_id":"x"}]') $$, '22023', null, 'a malformed hand is refused');

-- A prune takes the rows with the analysis.
select is((public.prune_hand_analysis('analysis/51', 20000) ->> 'deleted')::int, jsonb_array_length(pg_temp.cases() -> 'cases'),
          'a prune of analysis/50 ...');
select is((select count(*)::int from public.analysis_checker_rows) + (select count(*)::int from public.analysis_checker_hands), 0,
          '... takes its checker rows and markers');

select * from finish();
rollback;
